args.new_string:
import { toggleNotification } from "@/app/actions";
import { getNotificationsEnabled } from "@/app/store";

export default function Home() {
  const enabled = getNotificationsEnabled();

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently: <strong>{enabled ? "ON" : "OFF"}</strong>
      </p>
      <form action={toggleNotification}>
        <button type="submit">
          Turn {enabled ? "Off" : "On"} Notifications
        </button>
      </form>
    </main>
  );
}

